import csv, math
from collections import defaultdict
IN="/app/input"
def load(p):
    with open(p) as f: return list(csv.DictReader(f))
pages=load(f"{IN}/activity_kit_pages.csv")
sections={s["section_id"]:s for s in load(f"{IN}/kit_sections.csv")}
stocks={s["stock_code"]:s for s in load(f"{IN}/stock_profiles.csv")}
BASE={"cover":1,"parent_guide":2,"map":4,"activity":4,"mission_cards":6,"bingo":9,"badge_certificate":4}
def eff(a,s): return math.floor(int(a)*100/int(s))
def emin(pt,b):
    m=BASE[pt]
    if b=="saddle_stitch" and pt in ("mission_cards","badge_certificate"): m+=2
    return m
by=defaultdict(list)
for r in pages: by[r["page_id"]].append(r)
CANON=["DPI_TOO_LOW","MARGIN_VIOLATION","BLEED_SHORT","INK_OVER","ELEMENT_COUNT_SHORT"]
def audit(r):
    sec=sections[r["section_id"]]; b=sec["binding"]; st=stocks[sec["stock_code"]]
    ed=eff(r["artwork_dpi"],r["placement_scale_pct"])
    fb=r["full_bleed_design"].strip().lower()=="true"
    f=[]
    if ed<int(st["min_dpi"]): f.append("DPI_TOO_LOW")
    if not fb and float(r["margin_in"])<float(st["min_margin_in"]): f.append("MARGIN_VIOLATION")
    if fb and float(r["bleed_in"])<float(st["min_bleed_in"]): f.append("BLEED_SHORT")
    if int(r["total_ink_pct"])>int(st["max_ink_pct"]): f.append("INK_OVER")
    m=emin(r["page_type"],b)
    if int(r["element_count"])<m: f.append("ELEMENT_COUNT_SHORT")
    f=[x for x in CANON if x in f]
    return "|".join(f) if f else "none", ed, m, int(r["element_count"]), float(r["margin_in"]), float(r["bleed_in"]), int(r["total_ink_pct"])
# Superseded rows
sup={"PG-04":"AW-1004","PG-12":"AW-1012","PG-18":"AW-1018","PG-27":"AW-1027"}
for r in pages:
    if r["artwork_id"] in sup.values():
        f,ed,m,ec,mg,bl,ik=audit(r)
        sec=sections[r["section_id"]]; st=stocks[sec["stock_code"]]
        print(f"SUPERSEDED {r['artwork_id']} pg{r['page_id']} rev{r['revision']} ({r['page_name']}, {sec['binding']}/{sec['stock_code']}): eff_dpi={ed} margin={mg} fb={r['full_bleed_design']} bleed={bl} ink={ik} elems={ec}/{m} -> {f}")
print("---- LIVE of those ----")
live={"PG-04":"AW-1034","PG-12":"AW-1030","PG-18":"AW-1031","PG-27":"AW-1032"}
for r in pages:
    if r["artwork_id"] in live.values():
        f,ed,m,ec,mg,bl,ik=audit(r)
        sec=sections[r["section_id"]]; st=stocks[sec["stock_code"]]
        print(f"LIVE {r['artwork_id']} pg{r['page_id']} rev{r['revision']} ({r['page_name']}, {sec['binding']}/{sec['stock_code']}): eff_dpi={ed} margin={mg} fb={r['full_bleed_design']} bleed={bl} ink={ik} elems={ec}/{m} -> {f}")

